import json,numpy as np
m0=json.load(open('/app/runs/000_initial/meta.json'));m=json.load(open('/app/runs/071_close_banana_crosswise/meta.json'))
def Tquat(p,q):
 w,x,y,z=q;R=np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)] ]);T=np.eye(4);T[:3,:3]=R;T[:3,3]=p;return T
E0=np.array(m0['cameras']['wrist_cam']['extrinsic_cv']);Twcam0=np.linalg.inv(np.block([[E0],[np.array([0,0,0,1])]]));p0=np.array(m0['proprio']['now'][8:11]);q0=np.array(m0['proprio']['now'][11:15]);Trel=np.linalg.inv(Tquat(p0,q0))@Twcam0
